39	func (db *db) getLocalCluster() *appv1.Cluster {
40		initLocalCluster.Do(func() {
41			info, err := db.kubeclientset.Discovery().ServerVersion()
42			if err == nil {
43				ver, verErr := version.ParseGeneric(info.GitVersion)
44				if verErr == nil {
45					localCluster.Info.ServerVersion = ver.String()
46				} else {
47					log.Warnf("Failed to parse Kubernetes server version: %v", verErr)
48				}
49				localCluster.Info.ConnectionState = appv1.ConnectionState{Status: appv1.ConnectionStatusSuccessful}
50			} else {
51				localCluster.Info.ConnectionState = appv1.ConnectionState{
52					Status:  appv1.ConnectionStatusFailed,
53					Message: err.Error(),
54				}
55			}
56		})
57		cluster := localCluster.DeepCopy()
58		now := metav1.Now()
59		cluster.Info.ConnectionState.ModifiedAt = &now
60		return cluster
61	}
