64	func (db *db) ListClusters(_ context.Context) (*appv1.ClusterList, error) {
65		clusterSecrets, err := db.listSecretsByType(common.LabelValueSecretTypeCluster)
66		if err != nil {
67			return nil, err
68		}
69		clusterList := appv1.ClusterList{
70			Items: make([]appv1.Cluster, 0),
71		}
72		settings, err := db.settingsMgr.GetSettings()
73		if err != nil {
74			return nil, err
75		}
76		inClusterEnabled := settings.InClusterEnabled
77		hasInClusterCredentials := false
78		for _, clusterSecret := range clusterSecrets {
79			cluster, err := SecretToCluster(clusterSecret)
80			if err != nil {
81				log.Errorf("could not unmarshal cluster secret %s", clusterSecret.Name)
82				continue
83			}
84			if cluster.Server == appv1.KubernetesInternalAPIServerAddr {
85				if inClusterEnabled {
86					hasInClusterCredentials = true
87					clusterList.Items = append(clusterList.Items, *cluster)
88				}
89			} else {
90				clusterList.Items = append(clusterList.Items, *cluster)
91			}
92		}
93		if inClusterEnabled && !hasInClusterCredentials {
94			clusterList.Items = append(clusterList.Items, *db.getLocalCluster())
95		}
96		return &clusterList, nil
97	}
