147	func (db *db) WatchClusters(ctx context.Context,
148		handleAddEvent func(cluster *appv1.Cluster),
149		handleModEvent func(oldCluster *appv1.Cluster, newCluster *appv1.Cluster),
150		handleDeleteEvent func(clusterServer string),
151	) error {
152		argoSettings, err := db.settingsMgr.GetSettings()
153		if err != nil {
154			return err
155		}
156	
157		localCls := db.getLocalCluster()
158		if argoSettings.InClusterEnabled {
159			localCls, err = db.GetCluster(ctx, appv1.KubernetesInternalAPIServerAddr)
160			if err != nil {
161				return fmt.Errorf("could not get local cluster: %w", err)
162			}
163			handleAddEvent(localCls)
164		}
165	
166		db.watchSecrets(
167			ctx,
168			common.LabelValueSecretTypeCluster,
169	
170			func(secret *corev1.Secret) {
171				cluster, err := SecretToCluster(secret)
172				if err != nil {
173					log.Errorf("could not unmarshal cluster secret %s", secret.Name)
174					return
175				}
176				if cluster.Server == appv1.KubernetesInternalAPIServerAddr {
177					if argoSettings.InClusterEnabled {
178						// change local cluster event to modified, since it cannot be added at runtime
179						handleModEvent(localCls, cluster)
180						localCls = cluster
181					}
182					return
183				}
184				handleAddEvent(cluster)
185			},
186	
187			func(oldSecret *corev1.Secret, newSecret *corev1.Secret) {
188				oldCluster, err := SecretToCluster(oldSecret)
189				if err != nil {
190					log.Errorf("could not unmarshal cluster secret %s", oldSecret.Name)
191					return
192				}
193				newCluster, err := SecretToCluster(newSecret)
194				if err != nil {
195					log.Errorf("could not unmarshal cluster secret %s", newSecret.Name)
196					return
197				}
198				if newCluster.Server == appv1.KubernetesInternalAPIServerAddr {
199					localCls = newCluster
200				}
201				handleModEvent(oldCluster, newCluster)
202			},
203	
204			func(secret *corev1.Secret) {
205				if string(secret.Data["server"]) == appv1.KubernetesInternalAPIServerAddr && argoSettings.InClusterEnabled {
206					// change local cluster event to modified, since it cannot be deleted at runtime, unless disabled.
207					newLocalCls := db.getLocalCluster()
208					handleModEvent(localCls, newLocalCls)
209					localCls = newLocalCls
210				} else {
211					handleDeleteEvent(string(secret.Data["server"]))
212				}
213			},
214		)
215	
216		return err
217	}
